import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/commands.md","filePath":"modules/gem/commands.md","lastUpdated":0}`),a={name:`modules/gem/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiGem 的主命令是 <code>/emakigem</code>，别名为 <code>/egem</code>、<code>/eg</code>。玩家用它打开镶嵌或开孔界面；管理员用它检查装备宝石状态、清理异常状态、重载配置和输出调试信息。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/emakigem help</code></td><td>无</td><td>输出命令帮助列表。不带参数执行 <code>/emakigem</code> 时同样显示。</td></tr><tr><td><code>/emakigem gui &lt;inlay|upgrade|extract|reroll|recalibrate|open&gt;</code></td><td><code>emakigem.use</code> 或 <code>emakigem.admin</code></td><td>打开指定模式的宝石 GUI。当前命令需要显式填写模式，写错模式按参数错误处理。</td></tr><tr><td><code>/emakigem reload</code></td><td><code>emakigem.reload</code> 或 <code>emakigem.admin</code></td><td>重载主配置、宝石定义、插槽物品、共鸣、条件、GUI 和语言文件。</td></tr><tr><td><code>/emakigem inspect [player]</code></td><td><code>emakigem.use</code> 或 <code>emakigem.admin</code></td><td>查看指定玩家或自己的主手装备宝石状态。</td></tr><tr><td><code>/emakigem reroll &lt;full|value|confirm|cancel|status&gt;</code></td><td><code>emakigem.use</code> 或 <code>emakigem.admin</code></td><td>对<strong>主手</strong>宝石生成或接受洗炼候选。见下方<a href="#洗炼命令">洗炼命令</a>。</td></tr><tr><td><code>/emakigem clearstate</code></td><td><code>emakigem.admin</code></td><td>清除主手物品的宝石层状态，适合调试或修复异常装备。</td></tr><tr><td><code>/emakigem convert-legacy [confirm]</code></td><td><code>emakigem.admin</code></td><td>把 <code>items/*.yml</code> 里已废弃的 <code>match</code> 块转换为 <code>matcher</code> + 顶层 <code>slot_groups</code>。不带参数只做预演；<code>confirm</code>（或 <code>--apply</code>）才实际改写，并为每个文件留 <code>.bak</code> 备份。详见<a href="./templates.html#从-match-迁移">模板与插槽</a>。</td></tr><tr><td><code>/emakigem debug</code></td><td><code>emakigem.debug</code> 或 <code>emakigem.admin</code></td><td>输出运行时调试信息。</td></tr></tbody></table><h2 id="gui-模式" tabindex="-1">GUI 模式 <a class="header-anchor" href="#gui-模式" aria-label="Permalink to “GUI 模式”">​</a></h2><p><code>gui</code> 命令支持六种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>作用</th><th>常见用途</th></tr></thead><tbody><tr><td><code>inlay</code></td><td>镶嵌宝石</td><td>玩家日常宝石操作。界面内可切换到取出。</td></tr><tr><td><code>extract</code></td><td>取出宝石</td><td>直接以取出模式打开。</td></tr><tr><td><code>upgrade</code></td><td>升级宝石</td><td>消耗 EmakiStrengthen 配方材料提升等级。</td></tr><tr><td><code>reroll</code></td><td>全量洗炼</td><td>重抽主手宝石的词缀。</td></tr><tr><td><code>recalibrate</code></td><td>数值洗炼</td><td>只重掷主手宝石现有词缀的数值。</td></tr><tr><td><code>open</code></td><td>开孔</td><td>使用开孔器解锁装备预留插槽。</td></tr></tbody></table><p>示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakigem gui inlay</span></span>
<span class="line"><span>/emakigem gui open</span></span></code></pre></div><h2 id="洗炼命令" tabindex="-1">洗炼命令 <a class="header-anchor" href="#洗炼命令" aria-label="Permalink to “洗炼命令”">​</a></h2><p><code>reroll</code> 子命令针对<strong>主手</strong>宝石操作，需要 <code>emakigem.use</code> 或 <code>emakigem.admin</code>：</p><table tabindex="0"><thead><tr><th>子命令</th><th>作用</th></tr></thead><tbody><tr><td><code>full</code></td><td>生成全量洗炼候选（重抽词缀本身），立即扣除 <code>full_cost</code>。</td></tr><tr><td><code>value</code></td><td>生成数值洗炼候选（只重掷数值），立即扣除 <code>value_cost</code>。</td></tr><tr><td><code>confirm</code></td><td>确认候选并写入主手宝石。</td></tr><tr><td><code>cancel</code></td><td>放弃候选并退费。</td></tr><tr><td><code>status</code></td><td>查看当前候选的类型、原词缀数、候选词缀数与剩余秒数。</td></tr></tbody></table><p>已有未结束的候选会话时，再次执行 <code>full</code> 或 <code>value</code> 会直接返回现有会话，不会重复扣费也不会重新生成候选。候选存活时间由 <code>config.yml</code> 的 <code>reroll.session_ttl_seconds</code> 控制。配置与结算规则见<a href="./gems.html#洗炼系统">宝石定义</a>。</p><p>如果希望玩家只通过菜单入口进入某一类操作，可以在其他菜单插件或 NPC 插件中执行对应命令，并把权限控制交给 <code>emakigem.use</code>。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakigem.use</code></td><td>true</td><td>允许使用基础宝石功能和打开 GUI。</td></tr><tr><td><code>emakigem.reload</code></td><td>op</td><td>允许重载配置。</td></tr><tr><td><code>emakigem.admin</code></td><td>op</td><td>允许检查、清理状态等管理操作。</td></tr><tr><td><code>emakigem.debug</code></td><td>op</td><td>允许输出调试信息。</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要镶嵌或提取宝石</td><td><code>/emakigem gui inlay</code></td><td>打开镶嵌界面。</td></tr><tr><td>玩家要给装备开孔</td><td><code>/emakigem gui open</code></td><td>打开开孔界面。</td></tr><tr><td>装备宝石状态异常</td><td><code>/emakigem inspect [player]</code></td><td>查看主手装备 gem layer、插槽和共鸣状态。</td></tr><tr><td>主手装备需要清理宝石层</td><td><code>/emakigem clearstate</code></td><td>移除主手物品的宝石状态。先备份。</td></tr><tr><td>改了宝石、插槽物品、共鸣或 GUI</td><td><code>/emakigem reload</code></td><td>重载运行配置。</td></tr></tbody></table><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to “常见操作”">​</a></h2><h3 id="打开宝石界面" tabindex="-1">打开宝石界面 <a class="header-anchor" href="#打开宝石界面" aria-label="Permalink to “打开宝石界面”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakigem gui inlay</span></span></code></pre></div><p>命令模式必须明确写 <code>inlay</code> 或 <code>open</code>。<code>gui.default_mode</code> 只作为 GUI 服务默认值，不替代命令参数。</p><h3 id="检查装备宝石状态" tabindex="-1">检查装备宝石状态 <a class="header-anchor" href="#检查装备宝石状态" aria-label="Permalink to “检查装备宝石状态”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakigem inspect Steve</span></span></code></pre></div><p>检查内容包括物品定义 ID、物品识别来源、已开放插槽索引和插槽宝石分配。排查“属性未生效”“宝石显示残留”“提取后效果未撤销”等问题时优先使用该命令。</p><h3 id="清理异常状态" tabindex="-1">清理异常状态 <a class="header-anchor" href="#清理异常状态" aria-label="Permalink to “清理异常状态”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakigem clearstate</span></span></code></pre></div><p>该命令会清除主手物品上的宝石状态。使用前建议备份玩家物品数据，并先通过 <code>inspect</code> 确认目标物品。清理后装备会失去宝石层记录，原有宝石效果不会再按正常流程保留。</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>GUI 打不开：检查玩家是否拥有 <code>emakigem.use</code>，并确认 GUI 模板目录存在。</li><li>开孔失败：检查目标装备是否匹配 <code>items/*.yml</code>，并确认存在未开放且类型匹配的预留插槽。</li><li>镶嵌失败：检查宝石 <code>socket_compatibility</code>、插槽类型、条件配置、费用配置和 <code>inlay_success</code>。</li><li>升级失败：检查宝石 <code>stages</code> 是否启用、是否已达 <code>max_level</code>，以及 EmakiStrengthen 是否安装并存在可用的强化配方。</li><li>洗炼失败：检查宝石 <code>reroll.enabled</code>、词缀池是否为空、主手是否握着该宝石，以及候选是否已超时。</li><li>属性未刷新：检查 EmakiAttribute 是否安装，装备是否重建，宝石效果是否写入 <code>ea_attribute</code>。</li></ul>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};